INSERT INTO [Categories] ([Id], [Name], [Slug], [Tagline], [Description], [AccentColor], [SecondaryColor], [Icon], [ImageUrl], [HoverImageUrl], [SortOrder]) VALUES
  (1, N'Anime', N'anime', N'Blades, spirits and endless arcs', N'From shonen battles to quiet slice-of-life journeys, the Anime realm collects series, films and studios that define Japanese animation.', N'#E11D48', N'#F9A8D4', N'katana', N'/media/images/categories/anime-a.webp', N'/media/images/categories/anime-b.webp', 1),
  (2, N'Gaming', N'gaming', N'Press start on legendary worlds', N'Open worlds, soulslike challenges and indie gems. The Gaming realm tracks the titles, heroes and soundtracks players love.', N'#22C55E', N'#D4AF37', N'controller', N'/media/images/categories/gaming-a.webp', N'/media/images/categories/gaming-b.webp', 2),
  (3, N'Movies', N'movies', N'Cinema that changed the multiverse', N'Blockbusters, animated landmarks and director-driven epics, curated with trailers, cast profiles and release news.', N'#F59E0B', N'#DC2626', N'film-reel', N'/media/images/categories/movies-a.webp', N'/media/images/categories/movies-b.webp', 3),
  (4, N'TV Shows', N'tv-shows', N'Binge-worthy sagas, season by season', N'Prestige dramas, animated series and streaming phenomena with season guides, characters and premiere events.', N'#3B82F6', N'#22D3EE', N'tv', N'/media/images/categories/tv-shows-a.webp', N'/media/images/categories/tv-shows-b.webp', 4),
  (5, N'K-Pop', N'k-pop', N'Light sticks up, the stage is yours', N'Albums, music videos, comeback schedules and group profiles from the artists leading the Korean wave.', N'#EC4899', N'#22D3EE', N'microphone', N'/media/images/categories/k-pop-a.webp', N'/media/images/categories/k-pop-b.webp', 5),
  (6, N'Comics', N'comics', N'Panels that built modern myth', N'Graphic novels and landmark runs from the publishers and creators who shaped superheroes and beyond.', N'#FACC15', N'#EF4444', N'mask', N'/media/images/categories/comics-a.webp', N'/media/images/categories/comics-b.webp', 6),
  (7, N'Manga', N'manga', N'Ink, paper and legendary arcs', N'Seinen, shonen and cult classics with volume guides, creator notes and character deep dives.', N'#E5E7EB', N'#DC2626', N'manga', N'/media/images/categories/manga-a.webp', N'/media/images/categories/manga-b.webp', 7),
  (8, N'Cosplay', N'cosplay', N'Craft the character, own the stage', N'Build guides, crafting techniques, photography tips and masquerade highlights from the cosplay community.', N'#A855F7', N'#D4AF37', N'cosplay-mask', N'/media/images/categories/cosplay-a.webp', N'/media/images/categories/cosplay-b.webp', 8);
