INSERT INTO [Contents] ([Id], [CategoryId], [Title], [Slug], [ContentType], [Format], [Synopsis], [Description], [ReleaseYear], [Creator], [Seasons], [Episodes], [TrailerUrl], [ImageUrl], [HoverImageUrl], [BannerUrl], [PopularityScore], [ViewCount], [AverageRating], [RatingCount], [LikeCount], [DislikeCount], [IsFeatured], [IsPublished], [CreatedAt]) VALUES
  (1, 1, N'Attack on Titan', N'attack-on-titan', N'Video', N'Series', N'Humanity survives behind colossal walls until the Titans break through, and Eren Yeager vows to uncover the truth behind the world''s cruelest mystery.', N'<p>Humanity survives behind colossal walls until the Titans break through, and Eren Yeager vows to uncover the truth behind the world''s cruelest mystery.</p><p>Attack on Titan (2013) comes from Wit Studio / MAPPA. Across 4 seasons, the series has built a devoted following for its action and dark fantasy storytelling.</p><p>Explore characters, media and related picks from the Anime realm below.</p>', 2013, N'Wit Studio / MAPPA', 4, 89, N'/media/video/anime-teaser.mp4', N'/media/images/content/attack-on-titan-a.webp', N'/media/images/content/attack-on-titan-b.webp', N'/media/images/content/attack-on-titan-a.webp', 541, 43075, 4.43, 564, 692, 6, 1, 1, DATEADD(MINUTE, -171360, SYSUTCDATETIME())),
  (2, 1, N'Demon Slayer: Kimetsu no Yaiba', N'demon-slayer-kimetsu-no-yaiba', N'Video', N'Series', N'After demons slaughter his family, Tanjiro Kamado joins the Demon Slayer Corps to cure his sister Nezuko and hunt the demon who started it all.', N'<p>After demons slaughter his family, Tanjiro Kamado joins the Demon Slayer Corps to cure his sister Nezuko and hunt the demon who started it all.</p><p>Demon Slayer: Kimetsu no Yaiba (2019) comes from ufotable. Across 4 seasons, the series has built a devoted following for its action and supernatural storytelling.</p><p>Explore characters, media and related picks from the Anime realm below.</p>', 2019, N'ufotable', 4, 63, N'/media/video/anime-teaser.mp4', N'/media/images/content/demon-slayer-kimetsu-no-yaiba-a.webp', N'/media/images/content/demon-slayer-kimetsu-no-yaiba-b.webp', N'/media/images/content/demon-slayer-kimetsu-no-yaiba-a.webp', 871, 32648, 3.9, 122, 143, 18, 1, 1, DATEADD(MINUTE, -79200, SYSUTCDATETIME())),
  (3, 1, N'Jujutsu Kaisen', N'jujutsu-kaisen', N'Video', N'Series', N'Yuji Itadori swallows a cursed finger and becomes the vessel of Ryomen Sukuna, pulling him into a hidden war between sorcerers and curses.', N'<p>Yuji Itadori swallows a cursed finger and becomes the vessel of Ryomen Sukuna, pulling him into a hidden war between sorcerers and curses.</p><p>Jujutsu Kaisen (2020) comes from MAPPA. Across 2 seasons, the series has built a devoted following for its action and supernatural storytelling.</p><p>Explore characters, media and related picks from the Anime realm below.</p>', 2020, N'MAPPA', 2, 47, N'/media/video/anime-teaser.mp4', N'/media/images/content/jujutsu-kaisen-a.webp', N'/media/images/content/jujutsu-kaisen-b.webp', N'/media/images/content/jujutsu-kaisen-a.webp', 922, 90248, 4.23, 446, 287, 22, 1, 1, DATEADD(MINUTE, -269280, SYSUTCDATETIME())),
  (4, 1, N'One Piece', N'one-piece', N'Video', N'Series', N'Monkey D. Luffy and the Straw Hat crew sail the Grand Line in search of the legendary treasure that will make him King of the Pirates.', N'<p>Monkey D. Luffy and the Straw Hat crew sail the Grand Line in search of the legendary treasure that will make him King of the Pirates.</p><p>One Piece (1999) comes from Toei Animation. Across 21 seasons, the series has built a devoted following for its adventure and comedy storytelling.</p><p>Explore characters, media and related picks from the Anime realm below.</p>', 1999, N'Toei Animation', 21, 1100, N'/media/video/anime-teaser.mp4', N'/media/images/content/one-piece-a.webp', N'/media/images/content/one-piece-b.webp', N'/media/images/content/one-piece-a.webp', 768, 12952, 4.49, 339, 324, 29, 0, 1, DATEADD(MINUTE, -110880, SYSUTCDATETIME())),
  (5, 1, N'Naruto Shippuden', N'naruto-shippuden', N'Video', N'Series', N'Naruto Uzumaki returns to the Hidden Leaf after years of training, ready to rescue Sasuke and face the Akatsuki.', N'<p>Naruto Uzumaki returns to the Hidden Leaf after years of training, ready to rescue Sasuke and face the Akatsuki.</p><p>Naruto Shippuden (2007) comes from Studio Pierrot. Across 21 seasons, the series has built a devoted following for its action and adventure storytelling.</p><p>Explore characters, media and related picks from the Anime realm below.</p>', 2007, N'Studio Pierrot', 21, 500, N'/media/video/anime-teaser.mp4', N'/media/images/content/naruto-shippuden-a.webp', N'/media/images/content/naruto-shippuden-b.webp', N'/media/images/content/naruto-shippuden-a.webp', 797, 48850, 4.38, 132, 438, 37, 0, 1, DATEADD(MINUTE, -414720, SYSUTCDATETIME())),
  (6, 1, N'Fullmetal Alchemist: Brotherhood', N'fullmetal-alchemist-brotherhood', N'Video', N'Series', N'Brothers Edward and Alphonse Elric search for the Philosopher''s Stone after a forbidden transmutation costs them dearly.', N'<p>Brothers Edward and Alphonse Elric search for the Philosopher''s Stone after a forbidden transmutation costs them dearly.</p><p>Fullmetal Alchemist: Brotherhood (2009) comes from Bones. Across 1 season, the series has built a devoted following for its adventure and fantasy storytelling.</p><p>Explore characters, media and related picks from the Anime realm below.</p>', 2009, N'Bones', 1, 64, N'/media/video/anime-teaser.mp4', N'/media/images/content/fullmetal-alchemist-brotherhood-a.webp', N'/media/images/content/fullmetal-alchemist-brotherhood-b.webp', N'/media/images/content/fullmetal-alchemist-brotherhood-a.webp', 938, 79864, 4.82, 447, 567, 16, 0, 1, DATEADD(MINUTE, -316800, SYSUTCDATETIME())),
  (7, 1, N'Spy x Family', N'spy-x-family', N'Video', N'Series', N'A spy, an assassin and a telepathic child form a fake family, each hiding a secret from the others.', N'<p>A spy, an assassin and a telepathic child form a fake family, each hiding a secret from the others.</p><p>Spy x Family (2022) comes from Wit Studio / CloverWorks. Across 3 seasons, the series has built a devoted following for its comedy and action storytelling.</p><p>Explore characters, media and related picks from the Anime realm below.</p>', 2022, N'Wit Studio / CloverWorks', 3, 37, N'/media/video/anime-teaser.mp4', N'/media/images/content/spy-x-family-a.webp', N'/media/images/content/spy-x-family-b.webp', N'/media/images/content/spy-x-family-a.webp', 649, 18108, 4.76, 761, 565, 6, 0, 1, DATEADD(MINUTE, -465120, SYSUTCDATETIME())),
  (8, 1, N'Frieren: Beyond Journey''s End', N'frieren-beyond-journey-s-end', N'Video', N'Series', N'An elf mage who outlived her heroic party retraces their old journey and learns what the years with them truly meant.', N'<p>An elf mage who outlived her heroic party retraces their old journey and learns what the years with them truly meant.</p><p>Frieren: Beyond Journey''s End (2023) comes from Madhouse. Across 2 seasons, the series has built a devoted following for its fantasy and adventure storytelling.</p><p>Explore characters, media and related picks from the Anime realm below.</p>', 2023, N'Madhouse', 2, 38, N'/media/video/anime-teaser.mp4', N'/media/images/content/frieren-beyond-journey-s-end-a.webp', N'/media/images/content/frieren-beyond-journey-s-end-b.webp', N'/media/images/content/frieren-beyond-journey-s-end-a.webp', 913, 31205, 4.79, 164, 671, 29, 0, 1, DATEADD(MINUTE, -504000, SYSUTCDATETIME())),
  (9, 1, N'Chainsaw Man', N'chainsaw-man', N'Video', N'Series', N'Debt-ridden Denji merges with his chainsaw devil dog Pochita and is recruited as a Public Safety Devil Hunter.', N'<p>Debt-ridden Denji merges with his chainsaw devil dog Pochita and is recruited as a Public Safety Devil Hunter.</p><p>Chainsaw Man (2022) comes from MAPPA. Across 1 season, the series has built a devoted following for its action and horror storytelling.</p><p>Explore characters, media and related picks from the Anime realm below.</p>', 2022, N'MAPPA', 1, 12, N'/media/video/anime-teaser.mp4', N'/media/images/content/chainsaw-man-a.webp', N'/media/images/content/chainsaw-man-b.webp', N'/media/images/content/chainsaw-man-a.webp', 831, 88985, 4.95, 601, 692, 32, 0, 1, DATEADD(MINUTE, -360000, SYSUTCDATETIME())),
  (10, 1, N'My Hero Academia', N'my-hero-academia', N'Video', N'Series', N'Born without a Quirk, Izuku Midoriya inherits the power of the world''s greatest hero and enrolls at U.A. High.', N'<p>Born without a Quirk, Izuku Midoriya inherits the power of the world''s greatest hero and enrolls at U.A. High.</p><p>My Hero Academia (2016) comes from Bones. Across 8 seasons, the series has built a devoted following for its superhero and action storytelling.</p><p>Explore characters, media and related picks from the Anime realm below.</p>', 2016, N'Bones', 8, 170, N'/media/video/anime-teaser.mp4', N'/media/images/content/my-hero-academia-a.webp', N'/media/images/content/my-hero-academia-b.webp', N'/media/images/content/my-hero-academia-a.webp', 721, 36463, 3.91, 193, 701, 38, 0, 1, DATEADD(MINUTE, -344160, SYSUTCDATETIME())),
  (11, 1, N'Cowboy Bebop', N'cowboy-bebop', N'Video', N'Series', N'Bounty hunters aboard the spaceship Bebop chase criminals across the solar system to a jazz soundtrack.', N'<p>Bounty hunters aboard the spaceship Bebop chase criminals across the solar system to a jazz soundtrack.</p><p>Cowboy Bebop (1998) comes from Sunrise. Across 1 season, the series has built a devoted following for its sci-fi and action storytelling.</p><p>Explore characters, media and related picks from the Anime realm below.</p>', 1998, N'Sunrise', 1, 26, N'/media/video/anime-teaser.mp4', N'/media/images/content/cowboy-bebop-a.webp', N'/media/images/content/cowboy-bebop-b.webp', N'/media/images/content/cowboy-bebop-a.webp', 686, 91986, 4.41, 563, 539, 27, 0, 1, DATEADD(MINUTE, -417600, SYSUTCDATETIME())),
