INSERT INTO [CharacterProfiles] ([Id], [CategoryId], [ContentId], [Name], [Slug], [Fandom], [Role], [Power], [Quote], [Bio], [Strength], [Intelligence], [Agility], [Charisma], [ImageUrl], [HoverImageUrl], [ViewCount], [PopularityScore], [CreatedAt]) VALUES
  (1, 1, 1, N'Eren Yeager', N'eren-yeager', N'Attack on Titan', N'Protagonist', N'Attack Titan', N'If you win, you live. If you lose, you die.', N'A fierce young soldier of the Survey Corps who can transform into a Titan and whose quest for freedom reshapes his entire world.', 88, 74, 80, 70, N'/media/images/characters/eren-yeager-a.webp', N'/media/images/characters/eren-yeager-b.webp', 19865, 554, DATEADD(MINUTE, -295200, SYSUTCDATETIME())),
  (2, 1, 2, N'Tanjiro Kamado', N'tanjiro-kamado', N'Demon Slayer', N'Protagonist', N'Water and Sun Breathing', N'No matter how many people you may lose, you have no choice but to go on living.', N'A kind-hearted boy with an extraordinary sense of smell who became a Demon Slayer to save his sister Nezuko.', 78, 72, 86, 90, N'/media/images/characters/tanjiro-kamado-a.webp', N'/media/images/characters/tanjiro-kamado-b.webp', 828, 854, DATEADD(MINUTE, -103680, SYSUTCDATETIME())),
  (3, 1, 3, N'Satoru Gojo', N'satoru-gojo', N'Jujutsu Kaisen', N'Mentor', N'Limitless and Six Eyes', N'Throughout heaven and earth, I alone am the honored one.', N'The strongest jujutsu sorcerer of his era and a teacher at Tokyo Jujutsu High who protects the next generation.', 96, 92, 95, 94, N'/media/images/characters/satoru-gojo-a.webp', N'/media/images/characters/satoru-gojo-b.webp', 6806, 632, DATEADD(MINUTE, -253440, SYSUTCDATETIME())),
  (4, 1, 4, N'Monkey D. Luffy', N'monkey-d-luffy', N'One Piece', N'Captain', N'Gum-Gum Fruit', N'I''m going to be King of the Pirates!', N'The rubber-bodied captain of the Straw Hat Pirates whose optimism turns rivals into lifelong allies.', 94, 55, 90, 98, N'/media/images/characters/monkey-d-luffy-a.webp', N'/media/images/characters/monkey-d-luffy-b.webp', 29587, 469, DATEADD(MINUTE, -298080, SYSUTCDATETIME())),
  (5, 2, 13, N'Link', N'link', N'The Legend of Zelda', N'Hero', N'Master Sword and Ultrahand', N'...', N'The silent champion of Hyrule who wakes again and again to defeat Ganon and protect Princess Zelda.', 80, 78, 88, 76, N'/media/images/characters/link-a.webp', N'/media/images/characters/link-b.webp', 18437, 849, DATEADD(MINUTE, -341280, SYSUTCDATETIME())),
  (6, 2, 15, N'Kratos', N'kratos', N'God of War', N'Protagonist', N'Leviathan Axe and Blades of Chaos', N'Boy.', N'The former Ghost of Sparta, now a father trying to teach his son to be better than the gods he once destroyed.', 99, 75, 70, 72, N'/media/images/characters/kratos-a.webp', N'/media/images/characters/kratos-b.webp', 19990, 656, DATEADD(MINUTE, -342720, SYSUTCDATETIME())),
  (7, 2, 17, N'Geralt of Rivia', N'geralt-of-rivia', N'The Witcher', N'Monster Hunter', N'Witcher Signs and Silver Sword', N'Evil is evil. Lesser, greater, middling, it''s all the same.', N'A mutated monster hunter for hire whose bond with his adopted daughter Ciri defines his journey.', 86, 82, 84, 68, N'/media/images/characters/geralt-of-rivia-a.webp', N'/media/images/characters/geralt-of-rivia-b.webp', 27398, 880, DATEADD(MINUTE, -231840, SYSUTCDATETIME())),
  (8, 2, 18, N'Cloud Strife', N'cloud-strife', N'Final Fantasy VII', N'Mercenary', N'Buster Sword and Limit Breaks', N'Let''s mosey.', N'A former SOLDIER turned mercenary who confronts his fractured memories while pursuing Sephiroth.', 88, 70, 85, 74, N'/media/images/characters/cloud-strife-a.webp', N'/media/images/characters/cloud-strife-b.webp', 21022, 572, DATEADD(MINUTE, -89280, SYSUTCDATETIME())),
  (9, 3, 25, N'Paul Atreides', N'paul-atreides', N'Dune', N'Protagonist', N'Prescience and Fremen training', N'The mystery of life isn''t a problem to solve, but a reality to experience.', N'The heir of House Atreides who becomes the Fremen messiah Muad''Dib on the desert planet Arrakis.', 70, 92, 80, 95, N'/media/images/characters/paul-atreides-a.webp', N'/media/images/characters/paul-atreides-b.webp', 36408, 431, DATEADD(MINUTE, -164160, SYSUTCDATETIME())),
  (10, 3, 26, N'Miles Morales', N'miles-morales', N'Spider-Verse', N'Hero', N'Venom Blast and Camouflage', N'Anyone can wear the mask.', N'A Brooklyn teenager and artist who became Spider-Man and challenges the rules of the Multiverse.', 76, 80, 94, 85, N'/media/images/characters/miles-morales-a.webp', N'/media/images/characters/miles-morales-b.webp', 14480, 701, DATEADD(MINUTE, -311040, SYSUTCDATETIME())),
  (11, 3, 27, N'Tony Stark', N'tony-stark', N'Avengers', N'Hero', N'Iron Man armor', N'I am Iron Man.', N'The genius inventor who built the Iron Man suit and made the ultimate sacrifice to save the universe.', 82, 99, 75, 96, N'/media/images/characters/tony-stark-a.webp', N'/media/images/characters/tony-stark-b.webp', 15235, 733, DATEADD(MINUTE, -135360, SYSUTCDATETIME())),
  (12, 3, 28, N'The Joker', N'the-joker', N'The Dark Knight', N'Villain', N'Chaos and manipulation', N'Why so serious?', N'An agent of chaos who tests Gotham''s morality and Batman''s code in The Dark Knight.', 55, 92, 60, 88, N'/media/images/characters/the-joker-a.webp', N'/media/images/characters/the-joker-b.webp', 7152, 635, DATEADD(MINUTE, -298080, SYSUTCDATETIME())),
  (13, 4, 37, N'Eleven', N'eleven', N'Stranger Things', N'Protagonist', N'Telekinesis', N'Friends don''t lie.', N'A girl with psychokinetic abilities who escaped Hawkins Lab and became the heart of her friend group.', 60, 70, 55, 82, N'/media/images/characters/eleven-a.webp', N'/media/images/characters/eleven-b.webp', 8918, 743, DATEADD(MINUTE, -408960, SYSUTCDATETIME())),
  (14, 4, 38, N'Joel Miller', N'joel-miller', N'The Last of Us', N'Protagonist', N'Survival instinct', N'You keep finding something to fight for.', N'A hardened smuggler whose mission to escort Ellie becomes the reason he keeps living.', 80, 72, 68, 66, N'/media/images/characters/joel-miller-a.webp', N'/media/images/characters/joel-miller-b.webp', 26360, 612, DATEADD(MINUTE, -419040, SYSUTCDATETIME())),
  (15, 4, 40, N'Jinx', N'jinx', N'Arcane', N'Anti-hero', N'Hextech inventions', N'I''m not a monster. I''m just ahead of the curve.', N'A brilliant, unpredictable inventor from Zaun whose broken bond with her sister Vi drives the story.', 58, 90, 88, 84, N'/media/images/characters/jinx-a.webp', N'/media/images/characters/jinx-b.webp', 20349, 955, DATEADD(MINUTE, -410400, SYSUTCDATETIME())),
  (16, 4, 42, N'Walter White', N'walter-white', N'Breaking Bad', N'Anti-hero', N'Chemistry genius', N'I am the one who knocks.', N'A chemistry teacher who turns to manufacturing methamphetamine and becomes the infamous Heisenberg.', 40, 97, 35, 80, N'/media/images/characters/walter-white-a.webp', N'/media/images/characters/walter-white-b.webp', 25275, 669, DATEADD(MINUTE, -269280, SYSUTCDATETIME())),
  (17, 5, 49, N'BTS', N'bts', N'BTS', N'Group', N'Global stadium performances', N'Love yourself, love myself, peace.', N'A seven-member group that broke global records and became one of the best-selling acts in history.', 85, 88, 92, 99, N'/media/images/characters/bts-a.webp', N'/media/images/characters/bts-b.webp', 30132, 648, DATEADD(MINUTE, -142560, SYSUTCDATETIME())),
  (18, 5, 50, N'BLACKPINK', N'blackpink', N'BLACKPINK', N'Group', N'Headline performances', N'BLACKPINK in your area.', N'A four-member girl group known for bold concepts and record-breaking music videos.', 82, 85, 90, 98, N'/media/images/characters/blackpink-a.webp', N'/media/images/characters/blackpink-b.webp', 33836, 709, DATEADD(MINUTE, -41760, SYSUTCDATETIME())),
  (19, 5, 51, N'Stray Kids', N'stray-kids', N'Stray Kids', N'Group', N'Self-produced sound', N'Stay, we''re here for you.', N'An eight-member group whose in-house producer unit 3RACHA writes much of their music.', 84, 86, 91, 93, N'/media/images/characters/stray-kids-a.webp', N'/media/images/characters/stray-kids-b.webp', 13305, 707, DATEADD(MINUTE, -138240, SYSUTCDATETIME())),
  (20, 5, 52, N'NewJeans', N'newjeans', N'NewJeans', N'Group', N'Signature Y2K style', N'Bunnies, we''re always together.', N'A five-member group recognised for its easy-listening sound and nostalgic visual identity.', 78, 84, 88, 95, N'/media/images/characters/newjeans-a.webp', N'/media/images/characters/newjeans-b.webp', 28713, 528, DATEADD(MINUTE, -341280, SYSUTCDATETIME())),
  (21, 6, 61, N'Rorschach', N'rorschach', N'Watchmen', N'Vigilante', N'Unyielding resolve', N'Never compromise. Not even in the face of Armageddon.', N'A masked vigilante with a shifting inkblot face and an absolute moral code.', 72, 80, 74, 40, N'/media/images/characters/rorschach-a.webp', N'/media/images/characters/rorschach-b.webp', 25086, 908, DATEADD(MINUTE, -57600, SYSUTCDATETIME())),
  (22, 6, 62, N'Dream of the Endless', N'dream-of-the-endless', N'The Sandman', N'Protagonist', N'Lord of the Dreaming', N'I am hope.', N'The anthropomorphic personification of dreams, rebuilding his kingdom after a century in captivity.', 90, 96, 70, 86, N'/media/images/characters/dream-of-the-endless-a.webp', N'/media/images/characters/dream-of-the-endless-b.webp', 20627, 437, DATEADD(MINUTE, -393120, SYSUTCDATETIME())),
  (23, 6, 72, N'Batman', N'batman', N'DC Comics', N'Hero', N'Detective skills and gadgets', N'I am vengeance. I am the night.', N'Bruce Wayne, the Dark Knight of Gotham City, who turned tragedy into a lifelong crusade.', 85, 96, 88, 80, N'/media/images/characters/batman-a.webp', N'/media/images/characters/batman-b.webp', 22614, 975, DATEADD(MINUTE, -233280, SYSUTCDATETIME())),
  (24, 6, 70, N'Mark Grayson', N'mark-grayson', N'Invincible', N'Hero', N'Viltrumite strength and flight', N'I''m not going to let you hurt anyone else.', N'The son of Omni-Man who must decide what kind of hero he will become.', 95, 70, 92, 78, N'/media/images/characters/mark-grayson-a.webp', N'/media/images/characters/mark-grayson-b.webp', 27633, 631, DATEADD(MINUTE, -407520, SYSUTCDATETIME())),
  (25, 7, 73, N'Guts', N'guts', N'Berserk', N'Protagonist', N'Dragonslayer and Berserker Armor', N'If you''re always worried about crushing the ants beneath you, you won''t be able to walk.', N'The Black Swordsman, a mercenary who survives impossible odds on his path of vengeance.', 98, 70, 78, 60, N'/media/images/characters/guts-a.webp', N'/media/images/characters/guts-b.webp', 33980, 692, DATEADD(MINUTE, -387360, SYSUTCDATETIME())),
  (26, 7, 76, N'Light Yagami', N'light-yagami', N'Death Note', N'Anti-hero', N'The Death Note', N'I am justice!', N'A brilliant student who uses a supernatural notebook to become the god of a new world.', 40, 99, 50, 90, N'/media/images/characters/light-yagami-a.webp', N'/media/images/characters/light-yagami-b.webp', 23448, 759, DATEADD(MINUTE, -300960, SYSUTCDATETIME())),
  (27, 7, 78, N'Thorfinn', N'thorfinn', N'Vinland Saga', N'Protagonist', N'Dual daggers and resolve', N'I have no enemies.', N'A Viking warrior who trades revenge for a vision of a land without war.', 82, 76, 92, 70, N'/media/images/characters/thorfinn-a.webp', N'/media/images/characters/thorfinn-b.webp', 34955, 625, DATEADD(MINUTE, -23040, SYSUTCDATETIME())),
  (28, 7, 79, N'Yoichi Isagi', N'yoichi-isagi', N'Blue Lock', N'Striker', N'Spatial awareness', N'I''m going to become the best striker in the world.', N'A striker whose spatial awareness and adaptability make him a standout of the Blue Lock project.', 70, 90, 86, 74, N'/media/images/characters/yoichi-isagi-a.webp', N'/media/images/characters/yoichi-isagi-b.webp', 28108, 938, DATEADD(MINUTE, -329760, SYSUTCDATETIME())),
  (29, 8, NULL, N'Marin Kitagawa', N'marin-kitagawa', N'My Dress-Up Darling', N'Cosplayer', N'Endless enthusiasm', N'Loving something is never something to be ashamed of.', N'A cheerful student whose passion for cosplay inspires friends to follow their own creative dreams.', 50, 72, 70, 97, N'/media/images/characters/marin-kitagawa-a.webp', N'/media/images/characters/marin-kitagawa-b.webp', 25889, 772, DATEADD(MINUTE, -192960, SYSUTCDATETIME())),
  (30, 8, NULL, N'2B', N'2b', N'NieR:Automata', N'Android', N'Virtuous Contract blade', N'Everything that lives is designed to end.', N'An elite YoRHa combat android and one of the most-cosplayed game characters in the world.', 88, 80, 95, 84, N'/media/images/characters/2b-a.webp', N'/media/images/characters/2b-b.webp', 37148, 786, DATEADD(MINUTE, -276480, SYSUTCDATETIME())),
  (31, 8, 9, N'Makima', N'makima', N'Chainsaw Man', N'Antagonist', N'Control Devil', N'Good dogs are rewarded.', N'The enigmatic Public Safety leader whose calm authority makes her a convention favorite.', 80, 95, 70, 96, N'/media/images/characters/makima-a.webp', N'/media/images/characters/makima-b.webp', 2409, 509, DATEADD(MINUTE, -187200, SYSUTCDATETIME())),
  (32, 8, NULL, N'Harley Quinn', N'harley-quinn', N'DC Comics', N'Anti-hero', N'Acrobatics and a giant mallet', N'Life is a game, and I''m the one with the rules.', N'A former psychiatrist turned chaotic anti-hero whose costumes are cosplay staples.', 70, 78, 92, 90, N'/media/images/characters/harley-quinn-a.webp', N'/media/images/characters/harley-quinn-b.webp', 14610, 579, DATEADD(MINUTE, -375840, SYSUTCDATETIME()));
INSERT INTO [Articles] ([Id], [CategoryId], [AuthorId], [Title], [Slug], [Excerpt], [Body], [ImageUrl], [HoverImageUrl], [ReadMinutes], [IsFeatured], [Status], [ViewCount], [PopularityScore], [PublishedAt], [CreatedAt]) VALUES
  (1, 1, 1, N'How Anime Conquered the World', N'how-anime-conquered-the-world', N'From late-night cult favorite to global streaming phenomenon, a look at the milestones that took anime mainstream.', N'<p>Anime was once a niche discovered through fan-subbed tapes and late-night broadcasts. Today it tops global streaming charts and fills stadium-sized conventions.</p><figure><img src="/media/images/articles/how-anime-conquered-the-world-b.webp" alt="How Anime Conquered the World illustration"><figcaption>How Anime Conquered the World</figcaption></figure><p>Landmark films proved animation could carry adult emotion and spectacle, while long-running series built communities that grew with their audiences year after year.</p><h3>Why it matters</h3><p>Streaming removed the final barrier. Simulcasts let fans on every continent watch new episodes within hours of Japan, turning each weekly release into a worldwide event.</p><blockquote>Fan Hub Plus editorial - part of the Featured Articles hub.</blockquote>', N'/media/images/articles/how-anime-conquered-the-world-a.webp', N'/media/images/articles/how-anime-conquered-the-world-b.webp', 3, 1, N'Published', 21043, 803, DATEADD(MINUTE, -15840, SYSUTCDATETIME()), DATEADD(MINUTE, -17280, SYSUTCDATETIME())),
  (2, 2, 1, N'Open Worlds: A Decade of Player Freedom', N'open-worlds-a-decade-of-player-freedom', N'The open-world games that redefined exploration, from Skyrim''s mountains to the Lands Between.', N'<p>Open-world design promises one thing: if you can see it, you can go there. Over the last decade that promise evolved into living ecosystems and emergent stories.</p><figure><img src="/media/images/articles/open-worlds-a-decade-of-player-freedom-b.webp" alt="Open Worlds: A Decade of Player Freedom illustration"><figcaption>Open Worlds: A Decade of Player Freedom</figcaption></figure><p>Developers learned to guide players without walls, using landmarks, light and curiosity rather than waypoints.</p><h3>Why it matters</h3><p>The result is a genre where every player''s journey is different, and communities trade discoveries like treasure maps.</p><blockquote>Fan Hub Plus editorial - part of the Featured Articles hub.</blockquote>', N'/media/images/articles/open-worlds-a-decade-of-player-freedom-a.webp', N'/media/images/articles/open-worlds-a-decade-of-player-freedom-b.webp', 3, 1, N'Published', 16295, 561, DATEADD(MINUTE, -28800, SYSUTCDATETIME()), DATEADD(MINUTE, -30240, SYSUTCDATETIME())),
  (3, 3, 1, N'The Spider-Verse Effect', N'the-spider-verse-effect', N'How two animated films rewrote the rules of what a superhero movie can look like.', N'<p>Into the Spider-Verse arrived with a comic-book visual language: halftone dots, frame-rate shifts and hand-drawn effects layered over CG.</p><figure><img src="/media/images/articles/the-spider-verse-effect-b.webp" alt="The Spider-Verse Effect illustration"><figcaption>The Spider-Verse Effect</figcaption></figure><p>Its success sparked a wave of stylized animation across the industry, with studios embracing painterly and graphic looks.</p><h3>Why it matters</h3><p>Across the Spider-Verse pushed further, giving every universe its own art style and proving audiences crave visual invention.</p><blockquote>Fan Hub Plus editorial - part of the Featured Articles hub.</blockquote>', N'/media/images/articles/the-spider-verse-effect-a.webp', N'/media/images/articles/the-spider-verse-effect-b.webp', 3, 1, N'Published', 15068, 925, DATEADD(MINUTE, -41760, SYSUTCDATETIME()), DATEADD(MINUTE, -43200, SYSUTCDATETIME())),
  (4, 4, 1, N'Prestige TV and the Age of Adaptation', N'prestige-tv-and-the-age-of-adaptation', N'Why games, novels and animation are now the richest source of award-winning television.', N'<p>Television budgets now rival feature films, and adaptations have become the most reliable path to event-level series.</p><figure><img src="/media/images/articles/prestige-tv-and-the-age-of-adaptation-b.webp" alt="Prestige TV and the Age of Adaptation illustration"><figcaption>Prestige TV and the Age of Adaptation</figcaption></figure><p>Game adaptations, once dismissed, now earn critical acclaim by focusing on character over spectacle.</p><h3>Why it matters</h3><p>For fans, it means beloved worlds get the time and craft they deserve across full seasons.</p><blockquote>Fan Hub Plus editorial - part of the Featured Articles hub.</blockquote>', N'/media/images/articles/prestige-tv-and-the-age-of-adaptation-a.webp', N'/media/images/articles/prestige-tv-and-the-age-of-adaptation-b.webp', 3, 1, N'Published', 7009, 782, DATEADD(MINUTE, -54720, SYSUTCDATETIME()), DATEADD(MINUTE, -56160, SYSUTCDATETIME())),
  (5, 5, 1, N'K-Pop''s Global Stage', N'k-pop-s-global-stage', N'The performances and milestones that turned K-Pop into a worldwide movement.', N'<p>K-Pop combines tightly choreographed performance, visual storytelling and direct fan engagement.</p><figure><img src="/media/images/articles/k-pop-s-global-stage-b.webp" alt="K-Pop''s Global Stage illustration"><figcaption>K-Pop''s Global Stage</figcaption></figure><p>Fandoms organize streaming, charity projects and light-stick oceans that make every concert a shared spectacle.</p><h3>Why it matters</h3><p>Each milestone opened doors for the next generation of groups to reach audiences around the world.</p><blockquote>Fan Hub Plus editorial - part of the Featured Articles hub.</blockquote>', N'/media/images/articles/k-pop-s-global-stage-a.webp', N'/media/images/articles/k-pop-s-global-stage-b.webp', 3, 0, N'Published', 1818, 958, DATEADD(MINUTE, -67680, SYSUTCDATETIME()), DATEADD(MINUTE, -69120, SYSUTCDATETIME())),
  (6, 6, 1, N'Watchmen at 40: Why It Still Matters', N'watchmen-at-40-why-it-still-matters', N'Alan Moore and Dave Gibbons'' landmark series continues to shape how we think about heroes.', N'<p>Watchmen asked what costumed heroes would really mean in a world on the brink of nuclear war.</p><figure><img src="/media/images/articles/watchmen-at-40-why-it-still-matters-b.webp" alt="Watchmen at 40: Why It Still Matters illustration"><figcaption>Watchmen at 40: Why It Still Matters</figcaption></figure><p>Its nine-panel grid, mirrored structure and layered storytelling made it a textbook of the comics form.</p><h3>Why it matters</h3><p>Four decades later, its questions about power and accountability echo across film, television and games.</p><blockquote>Fan Hub Plus editorial - part of the Featured Articles hub.</blockquote>', N'/media/images/articles/watchmen-at-40-why-it-still-matters-a.webp', N'/media/images/articles/watchmen-at-40-why-it-still-matters-b.webp', 3, 0, N'Published', 3571, 503, DATEADD(MINUTE, -80640, SYSUTCDATETIME()), DATEADD(MINUTE, -82080, SYSUTCDATETIME())),
  (7, 7, 1, N'Dark Fantasy''s Golden Age', N'dark-fantasy-s-golden-age', N'How Berserk inspired a generation of creators from manga to soulslike games.', N'<p>Kentaro Miura''s Berserk combined operatic scale with intimate tragedy, and its influence is visible across modern dark fantasy.</p><figure><img src="/media/images/articles/dark-fantasy-s-golden-age-b.webp" alt="Dark Fantasy''s Golden Age illustration"><figcaption>Dark Fantasy''s Golden Age</figcaption></figure><p>Game designers have openly cited its armor, beasts and bleak beauty as inspiration.</p><h3>Why it matters</h3><p>Its continuation after Miura''s passing shows how a creative legacy can be carried forward with care.</p><blockquote>Fan Hub Plus editorial - part of the Featured Articles hub.</blockquote>', N'/media/images/articles/dark-fantasy-s-golden-age-a.webp', N'/media/images/articles/dark-fantasy-s-golden-age-b.webp', 3, 0, N'Published', 4631, 622, DATEADD(MINUTE, -93600, SYSUTCDATETIME()), DATEADD(MINUTE, -95040, SYSUTCDATETIME())),
  (8, 8, 1, N'Cosplay 101: From First Costume to Masquerade Stage', N'cosplay-101-from-first-costume-to-masquerade-stage', N'A step-by-step roadmap for your first serious build, from reference sheets to stage walk-on.', N'<p>Every great cosplay begins with references: front, back and side views of the character plus close-ups of materials.</p><figure><img src="/media/images/articles/cosplay-101-from-first-costume-to-masquerade-stage-b.webp" alt="Cosplay 101: From First Costume to Masquerade Stage illustration"><figcaption>Cosplay 101: From First Costume to Masquerade Stage</figcaption></figure><p>Break the build into sections - fabric, armor, wig, props and makeup - and schedule each against your convention date.</p><h3>Why it matters</h3><p>Finally, rehearse. Judges reward confident character performance as much as craftsmanship.</p><blockquote>Fan Hub Plus editorial - part of the Featured Articles hub.</blockquote>', N'/media/images/articles/cosplay-101-from-first-costume-to-masquerade-stage-a.webp', N'/media/images/articles/cosplay-101-from-first-costume-to-masquerade-stage-b.webp', 3, 0, N'Published', 13826, 526, DATEADD(MINUTE, -106560, SYSUTCDATETIME()), DATEADD(MINUTE, -108000, SYSUTCDATETIME())),
  (9, 2, 1, N'Behind the Soundtrack: When Game Music Became Concert Music', N'behind-the-soundtrack-when-game-music-became-concert-music', N'Orchestras around the world now sell out performances of video game scores.', N'<p>Game music was once limited by tiny sound chips, yet composers created melodies that generations still hum.</p><figure><img src="/media/images/articles/behind-the-soundtrack-when-game-music-became-concert-music-b.webp" alt="Behind the Soundtrack: When Game Music Became Concert Music illustration"><figcaption>Behind the Soundtrack: When Game Music Became Concert Music</figcaption></figure><p>As hardware evolved, scores grew into full orchestral works recorded with live ensembles.</p><h3>Why it matters</h3><p>Today symphony orchestras tour game music concerts, introducing classical halls to new audiences.</p><blockquote>Fan Hub Plus editorial - part of the Featured Articles hub.</blockquote>', N'/media/images/articles/behind-the-soundtrack-when-game-music-became-concert-music-a.webp', N'/media/images/articles/behind-the-soundtrack-when-game-music-became-concert-music-b.webp', 3, 0, N'Published', 15786, 755, DATEADD(MINUTE, -119520, SYSUTCDATETIME()), DATEADD(MINUTE, -120960, SYSUTCDATETIME())),
  (10, 3, 1, N'Convention Season Guide 2026-27', N'convention-season-guide-2026-27', N'Plan your year: the biggest conventions and Fan Hub Plus meetups on the calendar.', N'<p>Convention season never really ends. From autumn comic cons to summer anime expos, there is always a stage to visit.</p><figure><img src="/media/images/articles/convention-season-guide-2026-27-b.webp" alt="Convention Season Guide 2026-27 illustration"><figcaption>Convention Season Guide 2026-27</figcaption></figure><p>Use the Fan Hub Plus Event Map to find events near you, bookmark them and follow ticket links.</p><h3>Why it matters</h3><p>Here is a quick timeline of the highlights on this year''s calendar.</p><blockquote>Fan Hub Plus editorial - part of the Featured Articles hub.</blockquote>', N'/media/images/articles/convention-season-guide-2026-27-a.webp', N'/media/images/articles/convention-season-guide-2026-27-b.webp', 3, 0, N'Published', 21637, 928, DATEADD(MINUTE, -132480, SYSUTCDATETIME()), DATEADD(MINUTE, -133920, SYSUTCDATETIME())),
  (11, 4, 1, N'Building a Fandom Community', N'building-a-fandom-community', N'What makes an online fan community welcoming, safe and fun to come back to.', N'<p>Healthy communities start with clear guidelines and moderators who enforce them fairly.</p><figure><img src="/media/images/articles/building-a-fandom-community-b.webp" alt="Building a Fandom Community illustration"><figcaption>Building a Fandom Community</figcaption></figure><p>Shared rituals - watch-alongs, weekly threads and events - give members a reason to return.</p><h3>Why it matters</h3><p>Most importantly, communities thrive when members can create, not just consume. That is why Fan Hub Plus supports fan submissions.</p><blockquote>Fan Hub Plus editorial - part of the Featured Articles hub.</blockquote>', N'/media/images/articles/building-a-fandom-community-a.webp', N'/media/images/articles/building-a-fandom-community-b.webp', 3, 0, N'Published', 29684, 500, DATEADD(MINUTE, -145440, SYSUTCDATETIME()), DATEADD(MINUTE, -146880, SYSUTCDATETIME())),
  (12, 1, 1, N'Studio Spotlight: The Art of the Opening Sequence', N'studio-spotlight-the-art-of-the-opening-sequence', N'Why anime openings are some of the most rewatched minutes in animation.', N'<p>An anime opening has ninety seconds to introduce characters, tone and themes while matching a song beat for beat.</p><figure><img src="/media/images/articles/studio-spotlight-the-art-of-the-opening-sequence-b.webp" alt="Studio Spotlight: The Art of the Opening Sequence illustration"><figcaption>Studio Spotlight: The Art of the Opening Sequence</figcaption></figure><p>Studios often assign their most ambitious animators to openings, making them showcases of style.</p><h3>Why it matters</h3><p>Fans rewatch, rank and debate openings, and many become as famous as the shows themselves.</p><blockquote>Fan Hub Plus editorial - part of the Featured Articles hub.</blockquote>', N'/media/images/articles/studio-spotlight-the-art-of-the-opening-sequence-a.webp', N'/media/images/articles/studio-spotlight-the-art-of-the-opening-sequence-b.webp', 3, 0, N'Published', 14443, 640, DATEADD(MINUTE, -158400, SYSUTCDATETIME()), DATEADD(MINUTE, -159840, SYSUTCDATETIME()));
