INSERT INTO [UpcomingReleases] ([Id], [CategoryId], [Title], [ReleaseType], [ReleaseDate], [IsDateConfirmed], [Studio], [Description], [ImageUrl], [HoverImageUrl], [ExternalUrl], [ViewCount], [CreatedAt]) VALUES
  (1, 2, N'Cyberpunk 2077: PureArts V & Yaiba Kusanagi Statue', N'Collector Edition', '2026-11-19', 1, N'CD Projekt Red & PureArts', N'Official 1/6 scale articulated collector statue featuring LED illumination, die-cast components, and interchangeable weapons.', N'/media/images/upcoming/cyberpunk-purearts-v-a.jpg?v=2', N'/media/images/upcoming/cyberpunk-purearts-v-b.jpg?v=2', NULL, 7337, DATEADD(MINUTE, -15840, SYSUTCDATETIME())),
  (2, 3, N'Marvel Legends: Retro Wolverine & Iron Man Collector Set', N'Action Figure', '2026-12-18', 1, N'Marvel & Hasbro Pulse', N'Vintage comic-accurate premium 6-inch action figure set with interchangeable battle-damaged hands, heads, and accessories.', N'/media/images/upcoming/marvel-legends-retro-pack-a.jpg?v=2', N'/media/images/upcoming/marvel-legends-retro-pack-b.jpg?v=2', NULL, 5962, DATEADD(MINUTE, -76320, SYSUTCDATETIME())),
  (3, 3, N'Game of Thrones: Iron Throne 1/4 Scale Replica', N'Prop Replica', '2026-12-18', 1, N'HBO & Dark Horse Direct', N'Hand-painted polystone masterpiece faithfully detailing the legendary seat of Westeros with weathered sword hilts.', N'/media/images/upcoming/game-of-thrones-iron-throne-a.jpg?v=2', N'/media/images/upcoming/game-of-thrones-iron-throne-b.jpg?v=2', NULL, 8573, DATEADD(MINUTE, -28800, SYSUTCDATETIME())),
  (4, 3, N'The Batman: Tactical Batsuit Collector Figure', N'Collector Figure', '2027-10-01', 1, N'DC Collectibles & McFarlane Toys', N'Ultra-detailed 7-inch figure with 22 moving parts, cloth wired cape, grappling hook, and Gotham gargoyle display base.', N'/media/images/upcoming/the-batman-tactical-suit-a.jpg?v=2', N'/media/images/upcoming/the-batman-tactical-suit-b.jpg?v=2', NULL, 4449, DATEADD(MINUTE, -28800, SYSUTCDATETIME())),
  (5, 3, N'Spider-Man: Classic & Symbiote Suit Figure', N'Sixth Scale Figure', '2027-12-17', 1, N'Marvel & Hot Toys', N'Sixth-scale collectible figure with tailored fabric suit, web shooter effects, and magnetic wall-crawling display stand.', N'/media/images/upcoming/spider-man-symbiote-classic-a.jpg?v=2', N'/media/images/upcoming/spider-man-symbiote-classic-b.jpg?v=2', NULL, 1907, DATEADD(MINUTE, -80640, SYSUTCDATETIME())),
  (6, 2, N'Marvel''s Wolverine: Adamantium Legacy Claws & Cowl', N'Prop Replica', '2026-10-15', 0, N'Marvel Studios & Sideshow', N'Life-size wearable Adamantium claws and battle-damaged cowl replica forged from aircraft-grade brushed aluminum.', N'/media/images/upcoming/marvel-wolverine-legacy-a.jpg?v=3', N'/media/images/upcoming/marvel-wolverine-legacy-b.jpg?v=3', NULL, 4143, DATEADD(MINUTE, -1440, SYSUTCDATETIME())),
  (7, 2, N'The Witcher 3: Geralt of Rivia Grandmaster Statue', N'PVC Statue', '2027-06-30', 0, N'CD Projekt Red & Dark Horse', N'Hand-sculpted Toussaint armor edition featuring silver sword, steel blade, trophy hook, and detailed stone relief pedestal.', N'/media/images/upcoming/witcher-geralt-grandmaster-a.jpg?v=2', N'/media/images/upcoming/witcher-geralt-grandmaster-b.jpg?v=2', NULL, 3345, DATEADD(MINUTE, -56160, SYSUTCDATETIME())),
  (8, 1, N'One Piece: Sun God Nika Luffy Gear 5 Statue', N'Life-Size Sculpture', '2026-12-12', 1, N'Toei Animation & MegaHouse', N'Dynamic sculpture capturing the Joy Boy awakening with translucent clouds, cloud ribbon aura, and laughing sculpt.', N'/media/images/upcoming/one-piece-luffy-gear-5-a.jpg?v=2', N'/media/images/upcoming/one-piece-luffy-gear-5-b.jpg?v=2', NULL, 5631, DATEADD(MINUTE, -64800, SYSUTCDATETIME())),
  (9, 4, N'Arcane: Jinx 1/6 Scale Deluxe Statue', N'Deluxe Statue', '2026-11-07', 1, N'Riot Games & PureArts', N'Deluxe hand-painted resin statue featuring Fishbones rocket launcher, neon graffiti base, and glowing LED chemical canisters.', N'/media/images/upcoming/arcane-jinx-figure-a.jpg?v=2', N'/media/images/upcoming/arcane-jinx-figure-b.jpg?v=2', NULL, 5313, DATEADD(MINUTE, -67680, SYSUTCDATETIME())),
  (10, 5, N'BTS Official Special Edition Light Stick (Army Bomb)', N'Concert Gear', '2026-10-30', 1, N'HYBE & BigHit Music', N'Bluetooth-syncable concert light stick with multi-color LED stage integration, vibration motor, and commemorative photocard set.', N'/media/images/upcoming/bts-official-light-stick-a.jpg?v=2', N'/media/images/upcoming/bts-official-light-stick-b.jpg?v=2', NULL, 2111, DATEADD(MINUTE, -61920, SYSUTCDATETIME())),
  (11, 6, N'Invincible: Omni-Man Deluxe Action Figure', N'Deluxe Figure', '2026-11-25', 1, N'Skybound & Diamond Select', N'Premium comic-accurate articulated figure with removable blood-splattered battle suit, alternate stern portraits, and flight stand.', N'/media/images/upcoming/invincible-omni-man-a.jpg?v=2', N'/media/images/upcoming/invincible-omni-man-b.jpg?v=2', NULL, 5612, DATEADD(MINUTE, -37440, SYSUTCDATETIME())),
  (12, 7, N'Death Note: Ryuk Deluxe Action Figure', N'Action Figure', '2027-01-20', 0, N'Shueisha & Good Smile Company', N'Eerie high-detail sculpt featuring articulated feathered wings, apple accessory, notebook, and sculpted graveyard plinth.', N'/media/images/upcoming/death-note-ryuk-figure-a.jpg?v=2', N'/media/images/upcoming/death-note-ryuk-figure-b.jpg?v=2', NULL, 7051, DATEADD(MINUTE, -57600, SYSUTCDATETIME())),
  (13, 8, N'The Mandalorian: Din Djarin & Grogu Collector Set', N'Collector Set', '2026-10-22', 1, N'Lucasfilm & Hot Toys', N'Authentic beskar armor detailing, wearable Grogu carrier pouch, pulse rifle, and interchangeable weathered pauldron.', N'/media/images/upcoming/the-mandalorian-din-djarin-a.jpg?v=2', N'/media/images/upcoming/the-mandalorian-din-djarin-b.jpg?v=2', NULL, 7665, DATEADD(MINUTE, -56160, SYSUTCDATETIME())),
  (14, 1, N'Elden Ring: Tree Sentinel Heavy Cavalry Statue', N'Resin Statue', '2027-02-14', 0, N'FromSoftware & Bandai Namco', N'Gilded heavy warhorse and golden halberd replica captured in majestic charge pose, cast in high-density cold-cast resin.', N'/media/images/upcoming/elden-ring-tree-sentinel-a.jpg?v=2', N'/media/images/upcoming/elden-ring-tree-sentinel-b.jpg?v=2', NULL, 6265, DATEADD(MINUTE, -63360, SYSUTCDATETIME())),
  (15, 5, N'aespa: Armageddon Special Edition Album & Photocard Set', N'Album & Merch', '2026-12-01', 1, N'SM Entertainment', N'Exclusive metallic CD packaging containing holographic member photocards, concept artbook, poster, and collector stickers.', N'/media/images/upcoming/aespa-armageddon-special-set-a.jpg?v=2', N'/media/images/upcoming/aespa-armageddon-special-set-b.jpg?v=2', NULL, 1844, DATEADD(MINUTE, -34560, SYSUTCDATETIME())),
  (16, 4, N'Breaking Bad: Walter White Heisenberg Collector Figure', N'Collector Figure', '2027-03-06', 0, N'Sony Pictures Television & Mezco Toyz', N'Iconic pork pie hat, glasses, removable jacket, duffel bag of cash, and signature blue crystal accessories in vintage packaging.', N'/media/images/upcoming/breaking-bad-heisenberg-figure-a.jpg?v=2', N'/media/images/upcoming/breaking-bad-heisenberg-figure-b.jpg?v=2', NULL, 7154, DATEADD(MINUTE, -70560, SYSUTCDATETIME()));
