INSERT INTO [Events] ([Id], [CategoryId], [Title], [Slug], [EventType], [Description], [Story], [City], [Country], [Venue], [Latitude], [Longitude], [StartDate], [EndDate], [TicketUrl], [ImageUrl], [HoverImageUrl], [IsHighlight], [ViewCount], [CreatedAt]) VALUES
  (1, 6, N'New York Comic Con', N'new-york-comic-con', N'Convention', N'The East Coast''s biggest celebration of comics, film, TV, games and cosplay.', N'<p>Four days of panels, exclusive reveals and a show floor where every realm meets under one roof.</p><p>The East Coast''s biggest celebration of comics, film, TV, games and cosplay.</p>', N'New York', N'USA', N'Javits Center', 40.7577, -74.0027, DATEADD(DAY, 14, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 17, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://www.newyorkcomiccon.com', N'/media/images/events/new-york-comic-con-a.webp', N'/media/images/events/new-york-comic-con-b.webp', 1, 11238, DATEADD(MINUTE, -89280, SYSUTCDATETIME())),
  (2, 8, N'MCM London Comic Con', N'mcm-london-comic-con', N'Convention', N'The UK''s leading pop culture event with a legendary cosplay masquerade.', N'<p>Thousands of cosplayers fill ExCeL for three days, and the masquerade stage crowns the country''s top builders.</p><p>The UK''s leading pop culture event with a legendary cosplay masquerade.</p>', N'London', N'UK', N'ExCeL London', 51.5081, 0.0294, DATEADD(DAY, 29, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 31, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://www.mcmcomiccon.com', N'/media/images/events/mcm-london-comic-con-a.webp', N'/media/images/events/mcm-london-comic-con-b.webp', 1, 9674, DATEADD(MINUTE, -66240, SYSUTCDATETIME())),
  (3, 6, N'Lucca Comics & Games', N'lucca-comics-and-games', N'Convention', N'Europe''s largest comics and games festival held inside a walled medieval city.', N'<p>Medieval streets transform into a living fandom universe with exhibitions, tournaments and parades.</p><p>Europe''s largest comics and games festival held inside a walled medieval city.</p>', N'Lucca', N'Italy', N'Historic Centre', 43.8429, 10.5027, DATEADD(DAY, 34, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 38, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://www.luccacomicsandgames.com', N'/media/images/events/lucca-comics-and-games-a.webp', N'/media/images/events/lucca-comics-and-games-b.webp', 1, 9429, DATEADD(MINUTE, -76320, SYSUTCDATETIME())),
  (4, 2, N'Paris Games Week', N'paris-games-week', N'Convention', N'France''s largest video game show with playable demos and esports stages.', N'<p>Players line up for unreleased demos while esports finals light up the main arena.</p><p>France''s largest video game show with playable demos and esports stages.</p>', N'Paris', N'France', N'Paris Expo Porte de Versailles', 48.8322, 2.2875, DATEADD(DAY, 35, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 39, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://www.parisgamesweek.com', N'/media/images/events/paris-games-week-a.webp', N'/media/images/events/paris-games-week-b.webp', 0, 5969, DATEADD(MINUTE, -8640, SYSUTCDATETIME())),
  (5, 1, N'Comic Market (Comiket)', N'comic-market-comiket', N'Convention', N'The world''s largest self-published comics fair.', N'<p>Circle tables stretch as far as the eye can see, filled with doujinshi from creators of every fandom.</p><p>The world''s largest self-published comics fair.</p>', N'Tokyo', N'Japan', N'Tokyo Big Sight', 35.6298, 139.7942, DATEADD(DAY, 96, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 97, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://www.comiket.co.jp', N'/media/images/events/comic-market-comiket-a.webp', N'/media/images/events/comic-market-comiket-b.webp', 1, 5936, DATEADD(MINUTE, -77760, SYSUTCDATETIME())),
  (6, 1, N'Jump Festa', N'jump-festa', N'Convention', N'Shueisha''s annual festival of Weekly Shonen Jump anime, manga and games.', N'<p>Stage events reveal next year''s anime adaptations and game announcements for Jump''s biggest series.</p><p>Shueisha''s annual festival of Weekly Shonen Jump anime, manga and games.</p>', N'Chiba', N'Japan', N'Makuhari Messe', 35.648, 140.0346, DATEADD(DAY, 86, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 87, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://www.jumpfesta.com', N'/media/images/events/jump-festa-a.webp', N'/media/images/events/jump-festa-b.webp', 0, 5846, DATEADD(MINUTE, -53280, SYSUTCDATETIME())),
  (7, 2, N'PAX East', N'pax-east', N'Convention', N'A celebration of gaming culture with indie showcases and tabletop halls.', N'<p>Indie developers, tabletop tournaments and concerts make PAX a player-first festival.</p><p>A celebration of gaming culture with indie showcases and tabletop halls.</p>', N'Boston', N'USA', N'Boston Convention Center', 42.3453, -71.045, DATEADD(DAY, 182, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 185, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://east.paxsite.com', N'/media/images/events/pax-east-a.webp', N'/media/images/events/pax-east-b.webp', 0, 7961, DATEADD(MINUTE, -8640, SYSUTCDATETIME())),
  (8, 1, N'Anime Expo', N'anime-expo', N'Convention', N'North America''s largest celebration of Japanese pop culture.', N'<p>Premieres, concerts and the Masquerade bring the anime community together every July in Los Angeles.</p><p>North America''s largest celebration of Japanese pop culture.</p>', N'Los Angeles', N'USA', N'Los Angeles Convention Center', 34.0403, -118.2696, DATEADD(DAY, 281, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 284, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://www.anime-expo.org', N'/media/images/events/anime-expo-a.webp', N'/media/images/events/anime-expo-b.webp', 1, 6001, DATEADD(MINUTE, -82080, SYSUTCDATETIME())),
  (9, 6, N'San Diego Comic-Con', N'san-diego-comic-con', N'Convention', N'The legendary convention where Hall H reveals shape the year in pop culture.', N'<p>Hall H lines form overnight as studios bring casts, trailers and surprises to the most famous stage in fandom.</p><p>The legendary convention where Hall H reveals shape the year in pop culture.</p>', N'San Diego', N'USA', N'San Diego Convention Center', 32.7065, -117.1618, DATEADD(DAY, 301, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 304, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://www.comic-con.org', N'/media/images/events/san-diego-comic-con-a.webp', N'/media/images/events/san-diego-comic-con-b.webp', 1, 7734, DATEADD(MINUTE, -14400, SYSUTCDATETIME())),
  (10, 2, N'gamescom', N'gamescom', N'Convention', N'The world''s largest gaming event with Opening Night Live.', N'<p>Opening Night Live kicks off five days of world premieres and hands-on demos.</p><p>The world''s largest gaming event with Opening Night Live.</p>', N'Cologne', N'Germany', N'Koelnmesse', 50.9466, 6.9828, DATEADD(DAY, 335, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 339, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://www.gamescom.global', N'/media/images/events/gamescom-a.webp', N'/media/images/events/gamescom-b.webp', 1, 9982, DATEADD(MINUTE, -10080, SYSUTCDATETIME())),
  (11, 2, N'Tokyo Game Show', N'tokyo-game-show', N'Convention', N'Asia''s premier game expo featuring major Japanese publishers.', N'<p>Japanese studios showcase their biggest titles and cosplayers line the halls between stages.</p><p>Asia''s premier game expo featuring major Japanese publishers.</p>', N'Chiba', N'Japan', N'Makuhari Messe', 35.648, 140.0346, DATEADD(DAY, 364, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 367, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://tgs.nikkeibp.co.jp', N'/media/images/events/tokyo-game-show-a.webp', N'/media/images/events/tokyo-game-show-b.webp', 0, 11716, DATEADD(MINUTE, -60480, SYSUTCDATETIME())),
  (12, 1, N'Japan Expo', N'japan-expo', N'Convention', N'Europe''s largest festival of Japanese culture, from manga to martial arts.', N'<p>Manga artists, J-Pop concerts and traditional culture share the stage for four days.</p><p>Europe''s largest festival of Japanese culture, from manga to martial arts.</p>', N'Paris', N'France', N'Paris-Nord Villepinte', 48.9731, 2.5156, DATEADD(DAY, 287, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 290, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://www.japan-expo-paris.com', N'/media/images/events/japan-expo-a.webp', N'/media/images/events/japan-expo-b.webp', 0, 8953, DATEADD(MINUTE, -106560, SYSUTCDATETIME())),
  (13, 5, N'KCON LA', N'kcon-la', N'Convention', N'A K-Pop convention and concert series celebrating Korean culture.', N'<p>Fan engagement by day, stadium-scale concerts by night: KCON is the K-Pop fan''s summer pilgrimage.</p><p>A K-Pop convention and concert series celebrating Korean culture.</p>', N'Los Angeles', N'USA', N'Crypto.com Arena', 34.043, -118.2673, DATEADD(DAY, 323, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 325, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://www.kconusa.com', N'/media/images/events/kcon-la-a.webp', N'/media/images/events/kcon-la-b.webp', 1, 995, DATEADD(MINUTE, -27360, SYSUTCDATETIME())),
  (14, 1, N'Otakon', N'otakon', N'Convention', N'A long-running fan-run celebration of East Asian pop culture.', N'<p>Run by fans for fans, Otakon blends panels, concerts and a vibrant artist alley.</p><p>A long-running fan-run celebration of East Asian pop culture.</p>', N'Washington, D.C.', N'USA', N'Walter E. Washington Convention Center', 38.9048, -77.023, DATEADD(DAY, 316, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 318, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://www.otakon.com', N'/media/images/events/otakon-a.webp', N'/media/images/events/otakon-b.webp', 0, 5520, DATEADD(MINUTE, -86400, SYSUTCDATETIME())),
  (15, 8, N'Dragon Con', N'dragon-con', N'Convention', N'A multi-genre convention famous for its cosplay parade.', N'<p>The Dragon Con parade turns downtown Atlanta into a street-level celebration of costumes.</p><p>A multi-genre convention famous for its cosplay parade.</p>', N'Atlanta', N'USA', N'Downtown Atlanta Hotels', 33.759, -84.388, DATEADD(DAY, 343, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 347, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://www.dragoncon.org', N'/media/images/events/dragon-con-a.webp', N'/media/images/events/dragon-con-b.webp', 0, 4386, DATEADD(MINUTE, -77760, SYSUTCDATETIME())),
  (16, 7, N'Anime NYC', N'anime-nyc', N'Convention', N'New York''s anime convention featuring manga publishers and premieres.', N'<p>Manga publishers announce new licenses while fans meet their favorite creators.</p><p>New York''s anime convention featuring manga publishers and premieres.</p>', N'New York', N'USA', N'Javits Center', 40.7577, -74.0027, DATEADD(DAY, 330, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 332, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://animenyc.com', N'/media/images/events/anime-nyc-a.webp', N'/media/images/events/anime-nyc-b.webp', 0, 5015, DATEADD(MINUTE, -53280, SYSUTCDATETIME())),
  (17, 8, N'Fan Hub Plus Cosplay Meetup - Karachi', N'fan-hub-plus-cosplay-meetup-karachi', N'Meetup', N'A seaside meetup for cosplayers with a photo walk and craft swap.', N'<p>Cosplayers gather at sunset for a photo walk along the waterfront followed by a prop-making swap table.</p><p>A seaside meetup for cosplayers with a photo walk and craft swap.</p>', N'Karachi', N'Pakistan', N'Port Grand', 24.8454, 66.9856, DATEADD(DAY, 23, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 23, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://fanhubplus.example/events/karachi-cosplay-meetup', N'/media/images/events/fan-hub-plus-cosplay-meetup-karachi-a.webp', N'/media/images/events/fan-hub-plus-cosplay-meetup-karachi-b.webp', 1, 136, DATEADD(MINUTE, -44640, SYSUTCDATETIME())),
  (18, 1, N'Fan Hub Plus Anime Screening Night - Lahore', N'fan-hub-plus-anime-screening-night-lahore', N'Screening', N'A big-screen anime film night with a community quiz.', N'<p>A packed hall watches a fan-voted classic, followed by trivia and a cosplay showcase.</p><p>A big-screen anime film night with a community quiz.</p>', N'Lahore', N'Pakistan', N'Alhamra Arts Council', 31.558, 74.3355, DATEADD(DAY, 51, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 51, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://fanhubplus.example/events/lahore-screening', N'/media/images/events/fan-hub-plus-anime-screening-night-lahore-a.webp', N'/media/images/events/fan-hub-plus-anime-screening-night-lahore-b.webp', 0, 3676, DATEADD(MINUTE, -17280, SYSUTCDATETIME())),
  (19, 2, N'Fan Hub Plus Game Night - Islamabad', N'fan-hub-plus-game-night-islamabad', N'Meetup', N'Retro and modern game stations with a fighting-game bracket.', N'<p>Players compete in a community bracket while newcomers try classic consoles.</p><p>Retro and modern game stations with a fighting-game bracket.</p>', N'Islamabad', N'Pakistan', N'F-9 Park Pavilion', 33.701, 73.025, DATEADD(DAY, 65, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 65, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://fanhubplus.example/events/islamabad-game-night', N'/media/images/events/fan-hub-plus-game-night-islamabad-a.webp', N'/media/images/events/fan-hub-plus-game-night-islamabad-b.webp', 0, 1376, DATEADD(MINUTE, -48960, SYSUTCDATETIME())),
  (20, 5, N'Fan Hub Plus K-Pop Random Play Dance - Karachi', N'fan-hub-plus-k-pop-random-play-dance-karachi', N'Meetup', N'A random play dance session for K-Pop dance covers.', N'<p>Songs shuffle, dancers jump in, and the crowd cheers every perfectly timed chorus.</p><p>A random play dance session for K-Pop dance covers.</p>', N'Karachi', N'Pakistan', N'Dolmen Mall Clifton Atrium', 24.8023, 67.0303, DATEADD(DAY, 72, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 72, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://fanhubplus.example/events/karachi-rpd', N'/media/images/events/fan-hub-plus-k-pop-random-play-dance-karachi-a.webp', N'/media/images/events/fan-hub-plus-k-pop-random-play-dance-karachi-b.webp', 0, 2992, DATEADD(MINUTE, -15840, SYSUTCDATETIME())),
  (21, 3, N'Fan Hub Plus Premiere Night - Dubai', N'fan-hub-plus-premiere-night-dubai', N'Premiere', N'A community premiere screening with themed photo zones.', N'<p>Fans in costume gather for opening night, with photo zones inspired by the film''s world.</p><p>A community premiere screening with themed photo zones.</p>', N'Dubai', N'UAE', N'Dubai Mall Cinema', 25.1972, 55.2796, DATEADD(DAY, 85, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 85, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://fanhubplus.example/events/dubai-premiere-night', N'/media/images/events/fan-hub-plus-premiere-night-dubai-a.webp', N'/media/images/events/fan-hub-plus-premiere-night-dubai-b.webp', 1, 11711, DATEADD(MINUTE, -73440, SYSUTCDATETIME())),
  (22, 7, N'Fan Hub Plus Manga Drawing Jam - Lahore', N'fan-hub-plus-manga-drawing-jam-lahore', N'Meetup', N'An ink-and-paper drawing jam for aspiring manga artists.', N'<p>Artists sketch side by side, trade panel techniques and exhibit their pages by the evening.</p><p>An ink-and-paper drawing jam for aspiring manga artists.</p>', N'Lahore', N'Pakistan', N'National College of Arts', 31.5686, 74.3094, DATEADD(DAY, 114, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 114, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://fanhubplus.example/events/lahore-drawing-jam', N'/media/images/events/fan-hub-plus-manga-drawing-jam-lahore-a.webp', N'/media/images/events/fan-hub-plus-manga-drawing-jam-lahore-b.webp', 0, 10238, DATEADD(MINUTE, -106560, SYSUTCDATETIME())),
  (23, 4, N'Fan Hub Plus Series Finale Party - London', N'fan-hub-plus-series-finale-party-london', N'Screening', N'A finale screening with fan theories and a live quiz.', N'<p>The audience trades theories before the lights dim, then celebrates together after the credits.</p><p>A finale screening with fan theories and a live quiz.</p>', N'London', N'UK', N'Prince Charles Cinema', 51.5114, -0.1302, DATEADD(DAY, 135, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 135, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://fanhubplus.example/events/london-finale-party', N'/media/images/events/fan-hub-plus-series-finale-party-london-a.webp', N'/media/images/events/fan-hub-plus-series-finale-party-london-b.webp', 0, 7573, DATEADD(MINUTE, -25920, SYSUTCDATETIME())),
  (24, 6, N'Fan Hub Plus Comic Swap - Toronto', N'fan-hub-plus-comic-swap-toronto', N'Meetup', N'Trade back issues and meet local creators.', N'<p>Long boxes line the tables as collectors trade issues and discover local independent creators.</p><p>Trade back issues and meet local creators.</p>', N'Toronto', N'Canada', N'Toronto Reference Library', 43.6719, -79.3868, DATEADD(DAY, 170, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), DATEADD(DAY, 170, CAST(CAST(SYSUTCDATETIME() AS date) AS datetime2)), N'https://fanhubplus.example/events/toronto-comic-swap', N'/media/images/events/fan-hub-plus-comic-swap-toronto-a.webp', N'/media/images/events/fan-hub-plus-comic-swap-toronto-b.webp', 0, 11173, DATEADD(MINUTE, -119520, SYSUTCDATETIME()));
INSERT INTO [ChatbotFaqs] ([Id], [Category], [Question], [Answer], [Keywords], [IsActive], [SortOrder], [HitCount], [CreatedAt]) VALUES
  (1, N'Platform', N'What is Fan Hub Plus?', N'Fan Hub Plus is a fandom universe platform that brings Anime, Gaming, Movies, TV Shows, K-Pop, Comics, Manga and Cosplay together in one place with curated content, media, events and a personal dashboard.', N'what,is,fan hub,about,platform', 1, 1, 68, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (2, N'Platform', N'Which categories are available?', N'There are eight realms: Anime, Gaming, Movies, TV Shows, K-Pop, Comics, Manga and Cosplay. Open the Realms menu in the navigation bar to explore them.', N'categories,realms,sections,available', 1, 2, 66, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (3, N'Account', N'How do I create an account?', N'Click Join Free in the top navigation, fill in your name, email and password, then verify your email using the link we send you.', N'create,account,register,sign up,join', 1, 3, 81, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (4, N'Account', N'I forgot my password. What should I do?', N'Use Forgot Password on the login page. We will email a secure reset link that is valid for 30 minutes.', N'forgot,password,reset,recover', 1, 4, 79, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (5, N'Account', N'How do I verify my email?', N'Open the verification email and click the link. You can resend it from your dashboard if it expired.', N'verify,email,verification,confirm', 1, 5, 6, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (6, N'Account', N'Can I change my avatar?', N'Yes. Go to Profile and Settings and upload a JPG, PNG or WEBP image up to 2 MB.', N'avatar,profile picture,photo,upload', 1, 6, 37, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (7, N'Account', N'How do I change my favorite fandoms?', N'Open Profile and Settings, add or remove favorite fandoms and choose your categories of interest, then save.', N'favorite,fandoms,interests,preferences', 1, 7, 16, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (8, N'Features', N'What is the difference between a visitor and a member?', N'Visitors can browse categories, previews and basic search. Members unlock full details, media playback, advanced filters, bookmarks, ratings, notes, feedback and fan submissions.', N'visitor,member,difference,limited,unlock', 1, 8, 13, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (9, N'Features', N'How do I bookmark something?', N'Click the bookmark icon on any content, character, media, article, event or merchandise card. You can add a personal note from your Bookmarks page.', N'bookmark,save,favorite,later', 1, 9, 111, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (10, N'Features', N'Can I add notes to bookmarks?', N'Yes. Every bookmark can hold a personal note. Edit it from the bookmark button or the Bookmarks and Notes page.', N'notes,note,bookmark', 1, 10, 53, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (11, N'Features', N'How do I share content?', N'Use the Share button to copy the link or share to WhatsApp, X or Facebook.', N'share,link,whatsapp,facebook,twitter,x', 1, 11, 29, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (12, N'Features', N'How do ratings work?', N'Members can give media and content a 1-5 star rating and a thumbs up or down. Averages update instantly.', N'rating,rate,stars,thumbs,like,dislike', 1, 12, 14, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (13, N'Features', N'How do I use advanced filters?', N'In the Explorer, filter by category, genre, release year, popularity and content type, then sort by latest, most popular or A-Z.', N'filter,filters,search,sort,advanced', 1, 13, 88, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (14, N'Features', N'Can I submit my own fan content?', N'Yes. Members can submit articles, fan art, cosplay and theories from Submit Fan Content. An admin reviews each submission before it goes public.', N'submit,fan content,article,post,publish', 1, 14, 8, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (15, N'Features', N'How long does submission review take?', N'Admins usually review submissions within 48 hours. Track the status on My Submissions: pending, approved or rejected.', N'review,approval,pending,status,submission', 1, 15, 116, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (16, N'Features', N'Where is my dashboard?', N'After logging in, click your avatar and choose Dashboard to see your activity, favorites, bookmarks and recommendations.', N'dashboard,home,my page', 1, 16, 13, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (17, N'Features', N'Does Fan Hub Plus sell merchandise?', N'No. The Merchandise Showcase is for discovery only. There is no cart or payment on Fan Hub Plus.', N'buy,purchase,cart,payment,shop,price,merchandise', 1, 17, 101, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (18, N'Features', N'What are Upcoming Releases?', N'A calendar of anticipated anime, games, movies, shows, comics and merchandise drops with countdown timers.', N'upcoming,releases,countdown,coming soon', 1, 18, 101, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (19, N'Events', N'How do I find events near me?', N'Open Events, allow location access and click Near Me. The map shows conventions, meetups and screenings around you.', N'events,near me,location,gps,map,nearby', 1, 19, 9, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (20, N'Events', N'Can I filter events by city?', N'Yes. The event calendar can be filtered by city and type, and each event has a ticket link.', N'city,filter,calendar,events', 1, 20, 75, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (21, N'Events', N'Where do I buy event tickets?', N'Each event includes an official ticket link that opens the organizer''s website.', N'ticket,tickets,book,event', 1, 21, 111, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (22, N'Media', N'What media is available?', N'The Multimedia Center has trailers, videos, animated explainers, soundtracks and podcasts, each filterable by tag and category.', N'media,video,audio,trailer,podcast,soundtrack', 1, 22, 94, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (23, N'Media', N'Why can''t I play a video?', N'Media playback is available to members. Log in or create a free account to unlock it.', N'play,video,locked,cannot,playback', 1, 23, 92, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (24, N'Accessibility', N'How do I switch to light mode?', N'Use the sun and moon toggle in the navigation bar. Your choice is remembered.', N'light mode,dark mode,theme,toggle', 1, 24, 49, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (25, N'Accessibility', N'Can I make the text bigger?', N'Yes. Use the A- / A / A+ controls in the navigation bar or in Profile and Settings.', N'font,size,text,bigger,accessibility', 1, 25, 4, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (26, N'Accessibility', N'Does the site support reduced motion?', N'Yes. If your system has reduced motion enabled, 3D camera movement and heavy animations are replaced with static scenes.', N'motion,animation,reduced,accessibility', 1, 26, 17, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (27, N'Platform', N'Is there a sitemap?', N'Yes. The Sitemap is at the bottom of the Home page and linked in the footer.', N'sitemap,pages,navigation', 1, 27, 56, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (28, N'Platform', N'How do I report a bug?', N'Open Feedback, choose Bug, describe the issue and submit. Admins track every report.', N'bug,report,issue,problem,feedback', 1, 28, 106, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (29, N'Platform', N'How do I suggest a feature?', N'Open Feedback and choose Suggestion. We read every idea.', N'suggestion,feature,idea,feedback', 1, 29, 71, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (30, N'Platform', N'Who manages the content?', N'Content is curated by the Fan Hub Plus admin team, who add, edit and moderate everything through the Control Panel.', N'admin,manage,content,curate', 1, 30, 94, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (31, N'Platform', N'Is my data safe?', N'Passwords are hashed, sessions use signed tokens and personal pages require authentication.', N'safe,security,privacy,data,password', 1, 31, 3, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (32, N'Chatbot', N'What can the assistant do?', N'I can answer questions about Fan Hub Plus, recommend content based on your interests and guide you through the main features step by step.', N'assistant,chatbot,help,what can you do', 1, 32, 96, DATEADD(MINUTE, -144000, SYSUTCDATETIME())),
  (33, N'Chatbot', N'Is my chat history saved?', N'For members, chat history is saved so conversations can continue later. You can view or clear it from Chat History.', N'history,chat,saved,conversation', 1, 33, 98, DATEADD(MINUTE, -144000, SYSUTCDATETIME()));
