INSERT INTO [FanSubmissions] ([Id], [UserId], [CategoryId], [Title], [SubmissionType], [Summary], [Body], [ImageUrl], [Status], [ReviewNote], [ReviewedById], [ReviewedAt], [ViewCount], [CreatedAt]) VALUES
  (1, 2, 1, N'Why Frieren Is the Most Rewatchable Fantasy Anime', N'Article', N'An in-depth exploration of how Frieren: Beyond Journey''s End redefines the fantasy genre through quiet emotional storytelling, brilliant animation, and profound reflections on time and companionship.', N'<p>Frieren: Beyond Journey''s End succeeds where many modern fantasy epics stumble: it lets quiet moments breathe and allows silence to speak louder than battle cries. Unlike traditional hero journeys that culminate with the defeat of the Demon King, Frieren starts after the world has already been saved.</p><p>What follows is a poignant, beautifully animated pilgrimage through centuries of memory. Every town visited, every spell learned, and every nostalgic flashback reframes the elf mage''s past with Himmel, Heiter, and Eisen. Its episodic pacing rewards rewatching, revealing subtle visual foreshadowing and character growth that make it an instant timeless masterpiece.</p>', N'/media/images/content/frieren-beyond-journey-s-end-a.webp', N'Approved', N'Great contribution, published to the hub.', 1, DATEADD(MINUTE, -1440, SYSUTCDATETIME()), 636, DATEADD(MINUTE, -5760, SYSUTCDATETIME())),
  (2, 2, 8, N'My First Worbla Armor Build', N'Cosplay', N'A detailed build diary and masterclass on crafting a full convention-grade Worbla fantasy armor set from blueprint sketches to metallic weather-finishing in eight weeks.', N'<p>Crafting full fantasy plate armor with Worbla was one of the most demanding yet rewarding creative journeys I have ever undertaken. Over eight intensive weeks, I transformed raw thermoplastic sheets, EVA high-density foam, and acrylic paints into a battle-ready convention centerpiece.</p><p>The process started with tailored paper patterns mapped directly onto a duct-tape cast, followed by beveling 5mm EVA foam cores. Sandwiching the foam between heat-activated Worbla sheets provided unmatched rigid structural durability while preserving fine relief detailing. After six coats of wood glue primer and wet sanding, dry-brushing metallic acrylics and oil washes brought the battle-worn steel textures to life.</p>', N'/media/images/articles/cosplay-101-from-first-costume-to-masquerade-stage-a.webp', N'Approved', N'Great contribution, published to the hub.', 1, DATEADD(MINUTE, -2880, SYSUTCDATETIME()), 455, DATEADD(MINUTE, -7200, SYSUTCDATETIME())),
  (3, 3, 2, N'Elden Ring Boss Tier List - Community Edition', N'Article', N'Ranking the toughest bosses in the Lands Between.', N'<p>This list ranks bosses by difficulty, design and spectacle, with notes on builds that helped.</p>', N'/media/images/submissions/elden-ring-boss-tier-list-community-edition-a.webp', N'Pending', NULL, NULL, NULL, 0, DATEADD(MINUTE, -8640, SYSUTCDATETIME())),
  (4, 3, 7, N'Berserk Golden Age Fan Art Series', N'Fan Art', N'A three-piece ink illustration series.', N'<p>Three ink illustrations inspired by the Golden Age arc, drawn with brush pens.</p>', N'/media/images/submissions/berserk-golden-age-fan-art-series-a.webp', N'Pending', NULL, NULL, NULL, 0, DATEADD(MINUTE, -10080, SYSUTCDATETIME())),
  (5, 4, 5, N'Stray Kids 5-STAR Album Review', N'Review', N'A track-by-track breakdown and review of Stray Kids'' explosive third studio album 5-STAR, analyzing the 3RACHA production mastery, hybrid genres, and vocal delivery.', N'<p>Stray Kids'' third full-length album 5-STAR represents the pinnacle of their self-produced evolution. Spearheaded by producer trio 3RACHA (Bang Chan, Changbin, and Han), the 12-track project fearlessly blends traditional Korean folk percussion, hyper-pop synths, boom-bap hip hop, and heavy boom-box basslines.</p><p>From the explosive cultural flex of the title track ''S-Class'' to the gritty bounce of ''TOPLINE'' featuring Tiger JK, and the emotive melodic introspection of ''Youtiful'' and ''Collision'', 5-STAR cements Stray Kids as undisputed global trailblazers defining modern K-pop soundscapes.</p>', N'/media/fanhub/k-pop/images/stray-kids-5-star.jpg', N'Approved', N'Great contribution, published to the hub.', 1, DATEADD(MINUTE, -7200, SYSUTCDATETIME()), 864, DATEADD(MINUTE, -11520, SYSUTCDATETIME())),
  (6, 4, 6, N'Watchmen Theory: The Clock Motif', N'Theory', N'Tracking the doomsday clock through every chapter.', N'<p>Every chapter ends closer to midnight. This theory maps the clock to each character arc.</p>', N'/media/images/submissions/watchmen-theory-the-clock-motif-a.webp', N'Rejected', N'Please expand the theory with page references.', 1, DATEADD(MINUTE, -8640, SYSUTCDATETIME()), 0, DATEADD(MINUTE, -12960, SYSUTCDATETIME())),
  (7, 5, 3, N'Spider-Verse Animation Breakdown', N'Article', N'How frame rates tell Miles''s story.', N'<p>Miles animates on twos early in the film and shifts as he gains confidence.</p>', N'/media/images/submissions/spider-verse-animation-breakdown-a.webp', N'Pending', NULL, NULL, NULL, 0, DATEADD(MINUTE, -14400, SYSUTCDATETIME())),
  (8, 5, 4, N'Arcane Season 2 Watch Guide', N'Article', N'Everything to remember before watching season two.', N'<p>A recap of the key relationships and cliffhangers from season one.</p>', N'/media/images/submissions/arcane-season-2-watch-guide-a.webp', N'Pending', N'Great contribution, published to the hub.', 1, DATEADD(MINUTE, -11520, SYSUTCDATETIME()), 396, DATEADD(MINUTE, -15840, SYSUTCDATETIME()));
